// Nodo Code: valida los datos del API y calcula KPIs del tipo de cambio USD/MXN
const data = $input.first().json;
const rates = data.rates || {};
const fechas = Object.keys(rates).sort();

// 1) Validación de calidad de datos
const problemas = [];
if (fechas.length === 0) problemas.push('El API no devolvió datos');
const valores = [];
for (const f of fechas) {
  const v = rates[f] && rates[f].MXN;
  if (typeof v !== 'number' || isNaN(v)) problemas.push('Valor faltante o no numérico en ' + f);
  else if (v <= 0) problemas.push('Valor no válido en ' + f);
  else valores.push({ fecha: f, mxn: v });
}
if (new Set(fechas).size !== fechas.length) problemas.push('Fechas duplicadas');

// 2) KPIs
const n = valores.length;
const ultimo = n ? valores[n - 1] : null;
const primero = n ? valores[0] : null;
const prom = n ? valores.reduce((s, x) => s + x.mxn, 0) / n : null;
const min = n ? valores.reduce((a, b) => (b.mxn < a.mxn ? b : a)) : null;
const max = n ? valores.reduce((a, b) => (b.mxn > a.mxn ? b : a)) : null;
const cambioPct = n > 1 ? ((ultimo.mxn - primero.mxn) / primero.mxn) * 100 : 0;

// 3) Regla de negocio: alerta si el tipo de cambio se movió más de 1.5% en el periodo
const UMBRAL_PCT = 1.5;
const alerta = problemas.length > 0 || Math.abs(cambioPct) > UMBRAL_PCT;

return [{
  json: {
    periodo: primero && ultimo ? primero.fecha + ' a ' + ultimo.fecha : 'sin datos',
    dias_con_dato: n,
    ultimo_tipo_cambio: ultimo ? ultimo.mxn : null,
    promedio: prom !== null ? Number(prom.toFixed(4)) : null,
    minimo: min ? min.mxn + ' (' + min.fecha + ')' : null,
    maximo: max ? max.mxn + ' (' + max.fecha + ')' : null,
    cambio_pct: Number(cambioPct.toFixed(2)),
    problemas_de_datos: problemas,
    alerta,
  },
}];
